function examining(){return `<div class="screen-heading">${visual('blick')}<div><div class="eyebrow">B1 Weitblick · B2 Perspektivwechsel</div><h1>Prüfen</h1><p>Wähle die Frage, die gerade zu deiner Arbeit passt. Es gibt keine feste Reihenfolge.</p></div></div><div class="grid exam-paths">${[['pruefen-a','A · VERSTEHEN','Was zeigt meine Aufgabe über das Können?'],['pruefen-b','B · GESTALTEN','Ich möchte meine Aufgabe weiterentwickeln.'],['pruefen-c','C · HANDELN','Ich möchte einen Verdachtsfall durchdenken.']].map(([id,title,description])=>`<a class="horizon horizon-link sand" href="#${id}"><div class="room">Arbeitsweg ${title.slice(0,1)}</div><h2>${title}</h2><p>${description}</p><span class="tile-action">Arbeitsweg öffnen</span></a>`).join('')}</div><div class="subtle"><h3>Begleitung für deinen Einstieg</h3><p>Sprich einen Coach an, wenn du neu in einen begleiteten Arbeitsweg einsteigst. Für C ist fachkundige Begleitung vorgesehen.</p><a href="#coaches">Coaches finden</a></div>`}
